/*
 * viewer.js -- the Three.js viewer for the temple generated by make_model.py.
 *
 * This is the WebGL counterpart of raster3d.py, and it is built to MATCH
 * that renderer as closely as a browser can, so the two frames can be
 * compared numerically (see webshot.py):
 *
 *   - camera: eye (11, 8, 11), target (0, 4.6, 0), up +y, fovy 50 deg,
 *     near 1, far 80 -- the pinned three-quarter view;
 *   - framebuffer: a fixed 512x512 canvas with setPixelRatio(1), so one
 *     canvas pixel is one framebuffer pixel;
 *   - texture: flipY = false. The pipeline flips v once in objio.py and
 *     the sampler flips it back, so the raw OBJ v is effectively a
 *     TOP-down texture coordinate; Three.js must not flip the image a
 *     third time. flipY = false is the one setting that must not change.
 *   - shading: MeshLambertMaterial with flat normals, one directional
 *     light along (0.35, 0.8, 0.65) plus ambient -- the same 0.3 / 0.7
 *     split as the NumPy renderer. The OBJ file carries no vn records,
 *     so OBJLoader emits non-indexed geometry and
 *     computeVertexNormals() lands on one normal per triangle: exactly
 *     the pipeline's flat per-triangle Lambert factor.
 *   - sRGB output, no tone mapping: 8-bit canvas pixels then use the
 *     same encoding the pipeline writes into its .ppm files.
 *
 * Expected differences against the NumPy frame: MSAA at silhouettes
 * (the pipeline takes one sample per pixel) and trilinear mip filtering
 * vs the pipeline's single-level choice; interiors should match closely.
 *
 * "Export PPM" re-renders and copies the canvas through a 2D context
 * (which yields top-down 8-bit RGBA) into a binary P6 file, webgl.ppm,
 * that compare.py can diff directly against out/webgl_ref.ppm.
 */

import * as THREE from 'three';
import { OrbitControls } from 'three/addons/controls/OrbitControls.js';
import { OBJLoader } from 'three/addons/loaders/OBJLoader.js';

// The pinned view and lighting of the NumPy renderer (raster3d.py).
const EYE = [11.0, 8.0, 11.0];
const TARGET = [0.0, 4.6, 0.0];
const FOVY_DEG = 50.0;
const NEAR = 1.0;
const FAR = 80.0;
const SIZE = 512;
const LIGHT_DIR = [0.35, 0.8, 0.65];
const AMBIENT = 0.3;
const DIFFUSE = 0.7;
const SKY_SRGB = [0.87, 0.90, 0.95];

// Three.js lights live in physically based units: the Lambert BRDF
// carries a 1/PI factor, so an intensity of PI reproduces "ambient 1" /
// "diffuse 1" as the NumPy renderer defines them.
const PI = Math.PI;

const status = document.getElementById('status');
if (new URLSearchParams(window.location.search).has('auto')) {
  document.body.classList.add('auto');  // headless shots show only the canvas
}

// --- renderer: fixed size, pixel ratio 1, sRGB, no tone mapping ----------
const renderer = new THREE.WebGLRenderer({
  antialias: true,          // MSAA: the plan expects softened edges
  preserveDrawingBuffer: true,  // so the export button may read the canvas
});
renderer.setPixelRatio(1);
renderer.setSize(SIZE, SIZE);
renderer.outputColorSpace = THREE.SRGBColorSpace;
renderer.toneMapping = THREE.NoToneMapping;
document.getElementById('app').appendChild(renderer.domElement);

// --- scene, sky, camera ---------------------------------------------------
const scene = new THREE.Scene();
// setRGB with an explicit color space, so the authored sRGB value is
// decoded into the working space exactly like the pipeline's colors.
scene.background = new THREE.Color().setRGB(...SKY_SRGB, THREE.SRGBColorSpace);

const camera = new THREE.PerspectiveCamera(FOVY_DEG, 1.0, NEAR, FAR);
camera.position.set(...EYE);
camera.up.set(0, 1, 0);
camera.lookAt(...TARGET);

const controls = new OrbitControls(camera, renderer.domElement);
controls.target.set(...TARGET);
controls.enableDamping = false;  // damping would keep moving between frames
controls.update();

// --- lights: ambient + one directional, split 0.3 / 0.7 -------------------
const ambientLight = new THREE.AmbientLight(0xffffff, AMBIENT * PI);
const sunLight = new THREE.DirectionalLight(0xffffff, DIFFUSE * PI);
// A DirectionalLight shines from its position toward its target; with the
// target at the origin, position = light_dir aims it along the pinned
// direction (a surface sees L = normalize(position)).
sunLight.position.set(...LIGHT_DIR);
scene.add(ambientLight, sunLight);

// --- texture: the PNG copy of data/relief.ppm -----------------------------
// Asset paths are relative to THIS folder: the viewer is always served
// with a data/ folder next to it (make_model.py fills web/data/, and the
// Pages workflow publishes the same layout), so it works both under
// "npx serve web" and under a server rooted at the repo.
const texture = new THREE.TextureLoader().load(
  'data/relief.png',
  undefined,
  undefined,
  () => { status.textContent = 'missing data/relief.png -- run python make_model.py'; }
);
texture.flipY = false;  // see the header: must match the pipeline's UVs
texture.colorSpace = THREE.SRGBColorSpace;
texture.wrapS = THREE.RepeatWrapping;
texture.wrapT = THREE.RepeatWrapping;
texture.magFilter = THREE.LinearFilter;              // bilinear, like stage 8
texture.minFilter = THREE.LinearMipmapLinearFilter;  // mip chain, like stage 9

// --- mesh: OBJ geometry with flat normals + Lambert ------------------------
const loader = new OBJLoader();
loader.load(
  'data/temple.obj',
  (group) => {
    group.traverse((child) => {
      if (!child.isMesh) return;
      // No vn records in the file and non-indexed geometry, so this gives
      // one normal per triangle -- flat shading, as in the pipeline.
      child.geometry.computeVertexNormals();
      child.material.dispose();
      child.material = new THREE.MeshLambertMaterial({ map: texture });
    });
    scene.add(group);
  },
  undefined,
  () => { status.textContent = 'missing data/temple.obj -- run python make_model.py'; }
);

// --- render loop ------------------------------------------------------------
function animate() {
  controls.update();
  renderer.render(scene, camera);
}
renderer.setAnimationLoop(animate);

// --- Export PPM: the comparison hook for compare.py -------------------------
document.getElementById('export').addEventListener('click', () => {
  renderer.render(scene, camera);  // a fresh buffer for this frame

  // Copying through a 2D canvas handles the bottom-up flip readPixels
  // would need; getImageData returns top-down 8-bit RGBA in display
  // (sRGB) encoding -- the same bytes the pipeline writes.
  const copy = document.createElement('canvas');
  copy.width = SIZE;
  copy.height = SIZE;
  const ctx = copy.getContext('2d');
  ctx.drawImage(renderer.domElement, 0, 0);
  const rgba = ctx.getImageData(0, 0, SIZE, SIZE).data;

  const rgb = new Uint8Array(SIZE * SIZE * 3);
  for (let i = 0, j = 0; i < rgba.length; i += 4) {
    rgb[j++] = rgba[i];
    rgb[j++] = rgba[i + 1];
    rgb[j++] = rgba[i + 2];
  }

  // Binary P6: exactly one whitespace byte (the \n) must separate the
  // header from the raster, as ppm_io.read_ppm enforces.
  const header = new TextEncoder().encode(`P6\n${SIZE} ${SIZE}\n255\n`);
  const blob = new Blob([header, rgb], { type: 'application/octet-stream' });
  const link = document.createElement('a');
  link.href = URL.createObjectURL(blob);
  link.download = 'webgl.ppm';
  link.click();
  URL.revokeObjectURL(link.href);
  status.textContent = `exported webgl.ppm (${SIZE}x${SIZE})`;
});
